<?php
namespace Tests\Feature;
use App\Models\{KendaraanPelanggan,Pelanggan,PengajuanMobil,User};
use App\Services\PengajuanMobilService;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\{DB,Schema};
use RuntimeException;
use Tests\TestCase;
class UsedCarSubmissionStage8ATest extends TestCase
{
 use DatabaseTransactions;
 private function user(string $role):User{return User::whereHas('role',fn($q)=>$q->where('nama_role',$role))->firstOrFail();}
 private function vehicle(int $customer):KendaraanPelanggan{$v=KendaraanPelanggan::where('id_pelanggan',$customer)->where('status','aktif')->first();if($v)return $v;$v=new KendaraanPelanggan();$v->forceFill(['id_pelanggan'=>$customer,'merk'=>'Toyota','model'=>'QA','tipe'=>'1.5','tahun'=>2022,'warna'=>'Hitam','transmisi'=>'automatic','bahan_bakar'=>'bensin','nomor_polisi'=>'QA-8A','nomor_rangka'=>'QA-RANGKA-8A-'.$customer,'nomor_mesin'=>'QA-MESIN-8A-'.$customer,'kilometer'=>1000,'status'=>'aktif'])->save();return $v;}
 public function test_baseline_tables_are_copied_without_financial_or_inventory_side_effects():void{$this->assertSame(2,PengajuanMobil::count());$this->assertSame(2,DB::table('inspeksi_mobil')->count());$this->assertSame(1,DB::table('pembelian_mobil_bekas')->count());$this->assertSame(1,DB::table('trade_in')->count());$this->assertSame(7,DB::table('transaksi')->count());$this->assertSame(11,DB::table('pembayaran')->count());}
 public function test_customer_submission_resolves_identity_and_copies_owned_vehicle():void{$u=$this->user('pelanggan');$v=$this->vehicle($u->pelanggan->id_pelanggan);$before=DB::table('transaksi')->count();$response=$this->actingAs($u)->post('/pelanggan/pengajuan-mobil',['id_kendaraan_pelanggan'=>$v->id_kendaraan_pelanggan,'harga_harapan'=>123456789,'id_pelanggan'=>999999,'status'=>'disetujui']);$response->assertRedirect();$p=PengajuanMobil::latest('id_pengajuan')->first();$this->assertSame($u->pelanggan->id_pelanggan,$p->id_pelanggan);$this->assertSame('diajukan',$p->status);$this->assertSame($before,DB::table('transaksi')->count());}
 public function test_customer_cannot_view_other_submission_or_mutate_internal_actions():void{$u=$this->user('pelanggan');$otherCustomer=Pelanggan::where('id_pelanggan','<>',$u->pelanggan->id_pelanggan)->firstOrFail();$other=app(PengajuanMobilService::class)->create($otherCustomer->id_pelanggan,$this->vehicle($otherCustomer->id_pelanggan)->id_kendaraan_pelanggan,'1','QA');$this->actingAs($u)->get('/pelanggan/pengajuan-mobil/'.$other->id_pengajuan)->assertForbidden();$this->actingAs($u)->post('/admin/pengajuan-mobil/'.$other->id_pengajuan.'/process')->assertForbidden();}
 public function test_native_transition_process_inspect_offer_and_decision():void{$u=$this->user('pelanggan');$v=$this->vehicle($u->pelanggan->id_pelanggan);$svc=app(PengajuanMobilService::class);$p=$svc->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,'1000000','QA');$actor=$this->user('petugas')->petugas->id_petugas;$svc->process($p->id_pengajuan);$i=$svc->startInspection($p->id_pengajuan,$actor,45000);$svc->saveInspection($p->id_pengajuan,['kondisi_mesin'=>'baik','kondisi_body'=>'cukup','kondisi_interior'=>'baik','kondisi_kelistrikan'=>'baik','kondisi_ban'=>'cukup','kondisi_suspensi'=>'baik','kondisi_ac'=>'baik','kondisi_dokumen'=>'lengkap','kilometer'=>45000,'catatan'=>'QA'],$actor);$svc->offer($p->id_pengajuan,'900000');$svc->decision($p->id_pengajuan,$u->pelanggan->id_pelanggan,'disetujui');$this->assertSame('disetujui',$p->fresh()->status);$this->assertSame('900000.00',(string)$i->fresh()->harga_penawaran);$this->assertTrue(Schema::hasTable('pembelian_mobil_bekas'));}
 public function test_invalid_transition_and_customer_inspection_are_blocked():void{$p=PengajuanMobil::firstOrFail();$svc=app(PengajuanMobilService::class);$this->expectException(RuntimeException::class);$svc->offer($p->id_pengajuan,'1');}
 public function test_accept_reject_race_has_single_winner():void{$u=$this->user('pelanggan');$v=$this->vehicle($u->pelanggan->id_pelanggan);$svc=app(PengajuanMobilService::class);$p=$svc->create($u->pelanggan->id_pelanggan,$v->id_kendaraan_pelanggan,'1','QA');$actor=$this->user('petugas')->petugas->id_petugas;$svc->process($p->id_pengajuan);$svc->startInspection($p->id_pengajuan,$actor,1);$svc->offer($p->id_pengajuan,'1');$svc->decision($p->id_pengajuan,$p->id_pelanggan,'disetujui');$this->expectException(RuntimeException::class);$svc->decision($p->id_pengajuan,$p->id_pelanggan,'ditolak');}
 public function test_no_inventory_or_trade_in_row_is_created_by_stage_8a():void{$before=DB::table('mobil')->count();$this->assertSame($before,DB::table('mobil')->count());$this->assertSame(1,DB::table('trade_in')->count());}
}
